#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

DAYS_10 = 10
DISPATCHES_10 = 36
DAYS_20 = 20
DISPATCHES_20 = 18


def money(value):
    return round(float(value) + 1e-12, 2)


def read_csv(path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def load_catalog(path):
    data = json.loads(path.read_text())
    programs = []
    for group in data.get('service_groups', []):
        for program in group.get('programs', []):
            if program.get('review_flag') == 'review':
                p = dict(program)
                p['service_group'] = group.get('group_name')
                programs.append(p)
    return programs


def load_site_overrides(path):
    selected = {}
    for row in read_csv(path):
        if row.get('approval_state') != 'approved':
            continue
        code = row['program_code']
        version = int(row['version_no'])
        active_sites = int(row['active_sites'])
        if code not in selected or version > selected[code]['version_no']:
            selected[code] = {'version_no': version, 'active_sites': active_sites}
    return selected


def load_cooler_costs(path):
    return {row['cooler_type']: float(row['cooler_cost_usd']) for row in read_csv(path)}


def load_payments(path, in_scope_programs):
    label_to_code = {}
    for p in in_scope_programs:
        labels = [p['program_name']] + list(p.get('known_labels', []))
        for label in labels:
            label_to_code[label] = p['program_code']
    payments = {}
    for row in read_csv(path):
        code = label_to_code.get(row['program_label'])
        if code is not None:
            payments[code] = float(row['payment_per_dispatch_per_site_usd'])
    return payments


def model_calculation(program, active_sites, payment, cooler_cost, days_per_dispatch, dispatches_per_year):
    revenue = payment * active_sites * dispatches_per_year
    drug_cost = (
        float(program['acquisition_cost_per_1000_units_usd'])
        * active_sites
        * float(program['units_per_day'])
        * days_per_dispatch
        * dispatches_per_year
        / 1000.0
    )
    # Critical: cooler cost is per site and per dispatch, so both multipliers are required.
    cooler_cost_total = cooler_cost * active_sites * dispatches_per_year
    margin = revenue - drug_cost - cooler_cost_total
    return {
        'annual_revenue': revenue,
        'annual_drug_cost': drug_cost,
        'annual_cooler_cost': cooler_cost_total,
        'annual_margin': margin,
    }


def main():
    programs = load_catalog(ROOT / 'program_catalog.json')
    programs_by_code = {p['program_code']: p for p in programs}
    site_overrides = load_site_overrides(ROOT / 'site_overrides.csv')
    cooler_costs = load_cooler_costs(ROOT / 'cooler_cost.csv')
    payments = load_payments(ROOT / 'contract_payment.csv', programs)

    output_programs = []
    for program in programs:
        code = program['program_code']
        if code not in payments:
            raise ValueError(f'Missing payment for in-scope program {code}')
        cooler_type = program['cooler_type']
        if cooler_type not in cooler_costs:
            raise ValueError(f'Missing cooler cost for type {cooler_type}')

        active_sites = site_overrides.get(code, {}).get('active_sites', int(program['default_active_sites']))
        payment = payments[code]
        cooler_cost = cooler_costs[cooler_type]
        calc10 = model_calculation(program, active_sites, payment, cooler_cost, DAYS_10, DISPATCHES_10)
        calc20 = model_calculation(program, active_sites, payment, cooler_cost, DAYS_20, DISPATCHES_20)
        margin_difference = calc20['annual_margin'] - calc10['annual_margin']

        output_programs.append({
            'program_code': code,
            'program_name': program['program_name'],
            'active_sites': active_sites,
            'payment_per_dispatch_per_site_usd': money(payment),
            'cooler_type': cooler_type,
            'cooler_cost_usd': money(cooler_cost),
            'annual_revenue_10_day': money(calc10['annual_revenue']),
            'annual_drug_cost_10_day': money(calc10['annual_drug_cost']),
            'annual_cooler_cost_10_day': money(calc10['annual_cooler_cost']),
            'annual_margin_10_day': money(calc10['annual_margin']),
            'annual_revenue_20_day': money(calc20['annual_revenue']),
            'annual_drug_cost_20_day': money(calc20['annual_drug_cost']),
            'annual_cooler_cost_20_day': money(calc20['annual_cooler_cost']),
            'annual_margin_20_day': money(calc20['annual_margin']),
            'annual_margin_difference': money(margin_difference),
        })

    output_programs.sort(key=lambda p: p['program_code'])

    total_10 = sum(p['annual_margin_10_day'] for p in output_programs)
    total_20 = sum(p['annual_margin_20_day'] for p in output_programs)
    total_difference = total_20 - total_10
    absolute_total_difference = abs(total_difference)
    decision = 'move_to_20_day' if absolute_total_difference < 10000 else 'keep_10_day'

    result = {
        'assumptions': {
            'currency': 'USD',
            'review_flag_included': 'review',
            'site_count_resolution': 'Use the highest version_no among approved site_overrides rows; otherwise use default_active_sites.',
            'payment_resolution': 'Match contract_payment program_label to program_name or known_labels for in-scope catalog programs.',
            'cooler_cost_resolution': 'Match each in-scope program cooler_type to cooler_cost_usd.',
            'models': {
                '10_day': {'days_per_dispatch': DAYS_10, 'dispatches_per_year': DISPATCHES_10},
                '20_day': {'days_per_dispatch': DAYS_20, 'dispatches_per_year': DISPATCHES_20},
            },
        },
        'programs': output_programs,
        'totals': {
            'total_annual_margin_10_day': money(total_10),
            'total_annual_margin_20_day': money(total_20),
            'total_difference': money(total_difference),
            'absolute_total_difference': money(absolute_total_difference),
        },
        'recommendation': {
            'decision': decision,
            'justification': (
                f"Absolute total margin difference is ${money(absolute_total_difference):,.2f}; "
                f"threshold for moving is less than $10,000, so decision is {decision}."
            ),
        },
    }

    (ROOT / 'oncocooler_analysis.json').write_text(json.dumps(result, indent=2) + '\n')
    summary_lines = [
        '# OncoCooler Dispatch Margin Summary',
        f"Total 10-day margin (USD): ${result['totals']['total_annual_margin_10_day']:,.2f}",
        f"Total 20-day margin (USD): ${result['totals']['total_annual_margin_20_day']:,.2f}",
        f"Absolute difference (USD): ${result['totals']['absolute_total_difference']:,.2f}",
        f"Decision: {decision}",
        result['recommendation']['justification'],
    ]
    (ROOT / 'oncocooler_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
